s_e=\sqrt{\frac1{n-1}\sum_{j=1}^{n}(e_j-b)^2},\qquad \mathrm{RMSE}^2=b^2+\frac{n-1}{n}s_e^2.
\end{gathered}
\tag{З.1}
$$

